import { nativeImage, type NativeImage } from 'electron'
import { join } from 'node:path'

/**
 * Generated by `npm run icon` from build/icon/tray.html. The path holds for
 * both the dev and production builds, since electron-vite emits main to
 * out/main — the same reasoning as app-icon.ts.
 */
const DIR = join(import.meta.dirname, '../../resources/tray')

/**
 * The pulse: fade out and back, one frame per entry. Each level is a rendered
 * file rather than an opacity applied here, because a template image's alpha
 * is the only thing macOS keeps when it tints the icon for the menu bar.
 */
const PULSE_LEVELS = [75, 50, 30, 30, 50, 75]

export type TrayImages = {
  /** The icon as it normally sits in the menu bar. */
  rest: NativeImage
  /** The pulse's frames in the order they play, ending before `rest` returns. */
  pulse: NativeImage[]
}

/**
 * The 1x file is named here; nativeImage picks up the `@2x` file beside it on
 * its own. Marked as a template so macOS tints it for light and dark menu bars.
 */
function load(name: string): NativeImage | null {
  const image = nativeImage.createFromPath(join(DIR, `${name}Template.png`))

  if (image.isEmpty()) {
    return null
  }

  image.setTemplateImage(true)

  return image
}

export function loadTrayImages(): TrayImages | null {
  const rest = load('tray')
  const levels = new Map<number, NativeImage>()

  for (const level of new Set(PULSE_LEVELS)) {
    const image = load(`tray-${level}`)

    if (image) {
      levels.set(level, image)
    }
  }

  if (!rest || levels.size !== new Set(PULSE_LEVELS).size) {
    // Silently running without a menu bar icon hides a broken path, so say so.
    console.warn(`No menu bar images in ${DIR}. Run \`npm run icon\` to generate them.`)

    return null
  }

  return { rest, pulse: PULSE_LEVELS.flatMap((level) => levels.get(level) ?? []) }
}
